import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { guard } from '@/lib/authz'

// Append a message to a conversation.
//
// Exists because a committed priority is written into the thread it came out
// of. The analysis is generated by /api/prescribe, which streams; this is how
// the finished text gets persisted so reopening the conversation on Thursday
// still shows the decision alongside the question that produced it.

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
)

export async function POST(request: NextRequest) {
  const denied = await guard(request, 'ask')
  if (denied) return denied

  try {
    const { threadId, role, content, meta } = await request.json()

    if (!threadId || !content?.trim()) {
      return NextResponse.json({ error: 'threadId and content are required' }, { status: 400 })
    }
    if (role && !['user', 'assistant', 'system'].includes(role)) {
      return NextResponse.json({ error: 'Unsupported role' }, { status: 400 })
    }

    const { data, error } = await supabaseAdmin
      .from('chat_messages')
      .insert({
        thread_id: threadId,
        role: role || 'assistant',
        content: String(content),
        meta: meta || null,
      })
      .select('id, role, content, meta, created_at')
      .single()

    if (error) throw error
    return NextResponse.json({ message: data })
  } catch (error: any) {
    console.error('Append message error:', error)
    return NextResponse.json({ error: error.message || 'Could not save the message' }, { status: 500 })
  }
}
